/**
 * What every managed-provisioning `slack` command shares: the CLI options,
 * the local app target, the authed control-plane client, and API error
 * rendering.
 */
import { basename, resolve as resolvePath } from "node:path";
import { envPrefixFromName, slackEnvKeys } from "../channels/slack/index.js";
import { resolveDeployAuth } from "./cli-deploy.js";
import { cursorExternalApiUrl, resolveApiKeySync } from "./cursor/credentials.js";
import { isAgentProjectDir, loadAgentProject } from "./discovery.js";
import { CLI_COMMAND_NAME as CLI } from "./distribution.js";
import { V1_MIGRATE_HINT } from "./hosted-hints.js";
import { openBrowser } from "./open-browser.js";
import { AgentServeSlackClient, SlackProvisionApiError, } from "./slack-provision-client.js";
import { SLACK_MANIFEST_OPT_IN_FILE } from "./slack-manifest-opt-in.js";
import { slugFromDirectoryName } from "./slug.js";
import { stderrPalette } from "./terminal-style.js";
const DEFAULT_WIZARD_POLL_INTERVAL_MS = 3_000;
const DEFAULT_WIZARD_POLL_TIMEOUT_MS = 60 * 60 * 1000;
export function resolveSlackAppTarget(options, err) {
    if (options.env === "both" && options.prod !== true) {
        err("Provisioning targets one env at a time; pass --prod for the prod app (default dev).\n");
        return 1;
    }
    const env = options.prod === true || options.env === "prod" ? "prod" : "dev";
    const dir = resolvePath(options.dir);
    // Backend slug rule, mirrored so the error names the real problem
    // instead of a generic 400.
    const slug = slugFromDirectoryName(basename(dir));
    if (slug === undefined || !/^[a-z0-9][a-z0-9_-]{0,63}$/.test(slug)) {
        err(`Could not derive a valid app slug from the directory name ${JSON.stringify(basename(dir))} (slugs start with a letter or digit; lowercase letters, digits, '-', '_'); rename the directory or pass --dir <agent>.\n`);
        return 1;
    }
    const name = options.name ?? basename(dir);
    const envPrefix = options.noPrefix === true ? undefined : (options.prefix ?? envPrefixFromName(basename(dir)));
    return { dir, name, slug, env, envPrefix, envKeys: slackEnvKeys(envPrefix) };
}
export function errStream(options) {
    return options.err ?? ((text) => void process.stderr.write(text));
}
/**
 * The Slack control plane is architecture v2 only: the dashboard wizard
 * stores the minted tokens on the v2 deployment. An agent that still sets
 * `architecture: "v1"` must migrate first. A directory that is not an agent
 * project yet takes the framework default (v2).
 */
async function declaresArchitectureV1(dir) {
    if (!(await isAgentProjectDir(dir))) {
        return false;
    }
    const project = await loadAgentProject(dir);
    return project.agent.architecture === "v1";
}
/**
 * Credentials → provisioning client → team id, sharing the deploy CLI's
 * resolution (stored login / CURSOR_API_KEY, `--team` override, GetMe
 * default-team fallback). Returns an exit code (error already rendered)
 * on failure.
 */
export async function prepareProvision(options) {
    const out = options.out ?? ((text) => void process.stdout.write(text));
    const err = errStream(options);
    const credential = resolveApiKeySync(options.apiKey === undefined ? undefined : { apiKey: options.apiKey });
    if (credential?.source === "service-account") {
        err(`A team service-account key cannot provision Slack apps. Sign in with \`${CLI} login\` or set CURSOR_API_KEY.\n`);
        return 1;
    }
    const auth = await resolveDeployAuth({
        team: options.team,
        apiKey: options.apiKey,
        fetchImpl: options.fetchImpl,
        err,
    });
    if (typeof auth === "number") {
        return auth;
    }
    // Loading the project imports its authored modules; do it only once the
    // credentials are known good.
    if (await declaresArchitectureV1(resolvePath(options.dir))) {
        err(`Slack apps provision only for architecture v2 agents. ${V1_MIGRATE_HINT}\n`);
        return 1;
    }
    // Provisioning routes live on the external API host beside deploys.
    return {
        client: new AgentServeSlackClient({
            backendUrl: cursorExternalApiUrl(),
            apiKey: auth.apiKey,
            fetchImpl: options.fetchImpl,
        }),
        teamId: auth.teamId,
        json: options.json === true,
        out,
        err,
        dim: (options.palette ?? stderrPalette()).dim,
        openBrowserImpl: options.openBrowserImpl ?? openBrowser,
        pollIntervalMs: options.connectPollIntervalMs ?? DEFAULT_WIZARD_POLL_INTERVAL_MS,
        pollTimeoutMs: options.connectPollTimeoutMs ?? DEFAULT_WIZARD_POLL_TIMEOUT_MS,
    };
}
/** What to do next, by backend error code. */
const SLACK_API_ERROR_HINTS = {
    manager_reauth_required: `Re-run \`${CLI} slack create\` and finish Slack consent in the dashboard.`,
    invalid_bot_scopes: `Fix botScopes in ${SLACK_MANIFEST_OPT_IN_FILE}, then run the command again.`,
};
export function renderSlackApiError(error, err) {
    if (!(error instanceof SlackProvisionApiError)) {
        throw error;
    }
    const hint = error.code === undefined ? undefined : SLACK_API_ERROR_HINTS[error.code];
    err(hint === undefined ? `${error.message}\n` : `${error.message}\n${hint}\n`);
    return 1;
}
